566	
567	    findings.forEach((finding) => {
568	      // Height estimate: title(10) + current(20) + rec(20) + ai(20) + meta(10) + pad = ~88
569	      const neededH = estimateFindingHeight(finding);
570	      if (y + neededH > 270) {
571	        addPage(doc);
572	        y = MARGIN + 5;
