873	function enhancedScoreInterpretation(score: number): string {
874	  if (score >= 85) return "Excellent";
875	  if (score >= 70) return "Good";
876	  if (score >= 55) return "Average";
877	  if (score >= 40) return "Below Average";
878	  return "Critical";
879	}
