import { useState } from "react";
import { Link } from "react-router-dom";
import { X, Sparkles } from "lucide-react";

const CURRENT_VERSION = "1.8";
const STORAGE_KEY = "convertscan:last_seen_version";

export function WhatsNewBanner() {
  const [dismissed, setDismissed] = useState<boolean>(() => {
    try {
      return localStorage.getItem(STORAGE_KEY) === CURRENT_VERSION;
    } catch {
      return false;
    }
  });

  function dismiss() {
    try {
      localStorage.setItem(STORAGE_KEY, CURRENT_VERSION);
    } catch {
      // storage unavailable — just hide in memory
    }
    setDismissed(true);
  }

  if (dismissed) return null;

  return (
    <div className="flex items-center gap-3 rounded-lg border border-indigo-200 bg-indigo-50 px-4 py-2.5 text-sm">
      <Sparkles className="h-4 w-4 shrink-0 text-indigo-500" aria-hidden="true" />
      <p className="flex-1 text-indigo-700">
        <span className="font-medium">New in v{CURRENT_VERSION}:</span>{" "}
        Performance optimizations, accessibility improvements, and security hardening.{" "}
        <Link
          to="/changelog"
          className="font-medium underline underline-offset-2 hover:text-indigo-900 transition-colors"
        >
          See what&apos;s new
        </Link>
      </p>
      <button
        onClick={dismiss}
        aria-label="Dismiss banner"
        className="ml-auto shrink-0 rounded p-0.5 text-indigo-400 hover:bg-indigo-100 hover:text-indigo-600 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500"
      >
        <X className="h-4 w-4" />
      </button>
    </div>
  );
}

